{
  "probability": 0.89,
  "range_low": 0.80,
  "range_high": 0.95,
  "summary": [
    "Base-rate anchor from post-1990 Hungarian elections: 2/3 majorities occurred in about 4 of 9 elections (~0.44).",
    "Key drivers push probability up: opposition unity behind the Tisza platform and electoral-system amplification of the leading bloc.",
    "Downsides: vote-splitting among smaller parties and polling divergence introduce uncertainty that tempers the forecast.",
    "Posterior probability: 0.89 with a plausible uncertainty range around 0.80–0.95."
  ],
  "confidence": "high",
  "narrative": "Starting from a 0.44 base-rate, consolidation around the Tisza platform and Hungary's pro-2/3 bias raise the odds of a supermajority. However, fragmentation, turnout variance, and mixed polling keep the outcome uncertain, yielding a calibrated posterior near 0.89 with a wide but bounded range.",
  "justification": {
    "anchor": {
      "probability": 0.44,
      "basis": "Base-rate anchor from post-1990 elections; 2/3 majorities occurred in 4 of 9 elections, implying a ~0.44 baseline."
    },
    "factor_updates": [
      {
        "factor": "Opposition unity behind Tisza coalition",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "FT and other sources indicate opposition coalescence around Tisza; polls show Tisza leading in some surveys, increasing the odds of a 2/3 for the coalition."
      },
      {
        "factor": "Electoral-system amplification of the largest bloc",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": " Hungary's system magnifies the leading vote share into a larger seat share, helping reach 133 seats if the leading bloc fares well."
      },
      {
        "factor": "Opposition fragmentation by smaller parties",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Several small parties near thresholds risk siphoning votes, which can limit the coalition's ability to reach 133 seats even if the lead is large."
      },
      {
        "factor": "Polling divergence across firms",
        "direction": "neutral",
        "magnitude": "moderate",
        "rationale": "Contradictory polls produce scenario-dependent probability for a 2/3 outcome; no single poll consensus."
      },
      {
        "factor": "Turnout dynamics: opposition turnout advantage",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Higher mobilization among opposition voters raises probability of a larger seat share for them in some models."
      },
      {
        "factor": "Fidesz turnout risk",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Turnout of inactive Fidesz supporters could be mobilized, potentially reducing the swing toward opposition 2/3."
      },
      {
        "factor": "Market signals and macro expectations",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Market commentary suggesting plausible opposition win nudges probabilities upward, though not decisive."
      }
    ],
    "synthesis_rationale": "An initial 0.44 anchor was updated by multiple factors; unity and system bias push probability upward, while fragmentation, turnout variance, and polling divergence pull it back. The combination yields a calibrated posterior around 0.89, with a range reflecting residual uncertainty."
  }
}

{
