  "range_low": 0.80,
  "range_high": 0.97,
  "summary": [
    "Anchor from post-1990 Hungarian elections places two-thirds-majority probability around 0.44.",
    "Opposition unity behind the Tisza platform and electoral-system amplification push odds toward the 133-seat threshold.",
    "Divergent polls and turnout uncertainty temper the forecast, but market signals and mobilization dynamics support a high-probability outcome.",
    "Calibrated posterior probability is 0.89 with an uncertainty range roughly 0.80–0.97."
  ],
  "confidence": "high",
  "narrative": "Starting from a 0.44 anchor based on historical frequency of 2/3 majorities, recent signals (opposition consolidation behind Tisza, plus systemic seat amplification) raise the odds toward 0.89. Poll divergence and turnout risk temper the move, yielding a calibrated range that remains high but not guaranteed.",
  "justification": {
    "anchor": {
      "probability": 0.44,
      "basis": "Historical frequency of any party or coalition achieving a two-thirds (133+) seat majority in post-1990 Hungarian parliamentary elections (4 of 9) as described in the reference class."
    },
    "factor_updates": [
      {
        "factor": "Opposition consolidation around the Tisza platform",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "FT and poll signals indicating opposition unity behind Tisza increase the likelihood of crossing the 133-seat threshold, elevating the probability toward a 2/3 outcome."
      },
      {
        "factor": "Electoral-system amplification of the largest bloc",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Winner-take-most dynamics in Hungary's system magnify the leading vote share into seats, making a 2/3 outcome more plausible if a bloc leads in votes."
      },
      {
        "factor": "Opposition fragmentation by smaller parties",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Presence of smaller parties entering parliament could split votes, reducing the chance of a clean 2/3 for a single bloc."
      },
      {
        "factor": "Polling divergence across firms",
        "direction": "neutral",
        "magnitude": "moderate",
        "rationale": "Conflicting polls reduce certainty about which coalition leads; this tempers the confidence of a 2/3 outcome despite other positives."
      },
      {
        "factor": "Market expectations and macro effects",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Financial-market commentary pricing in potential regime-change suggests a non-negligible probability of an opposition victory translating into a 2/3 outcome."
      },
      {
        "factor": "Mobilization dynamics: opposition turnout advantage",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Improved opposition mobilization increases anti-government votes and strengthens prospects for a high-seat share for the opposition."
      },
      {
        "factor": "Fidesz turnout risk: mobilization of inactive supporters",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "If large numbers of inactive Fidesz supporters are mobilized, the leading bloc's seat share could be eroded, reducing the odds of a 2/3 outcome."
      }
    ],
    "synthesis_rationale": "The posterior 0.89 results from integrating a historical anchor with multiple upward and downward updates. The strongest upward pushes come from opposition unity and systemic seat amplification, tempered by polling divergence and turnout risks. Correlations among factors warrant a calibrated, not naïve, aggregation, yielding a high but not certainty-filled outcome with a roughly 0.80–0.97 credible interval."
  }
}

